('ko-v2b-u4-l4-e4', 'ko-v2b-u4-l4', '4', 'FILL_BLANK', 'Escolha a palavra que completa a expressão.', 'Prazer em conhecer você: 만나서 ___.', '["반가워요","주세요","아니요"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '["반가워요"]'::jsonb, '{"accepted":["반가워요"]}'::jsonb, '만나서 반가워요 é a expressão completa para “Prazer em conhecer você”.', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING', 'ko_v2b_u4_l4_fill_blank', '5', null, '[]'::jsonb),
('ko-v2b-u4-l4-e5', 'ko-v2b-u4-l4', '5', 'WORD_ORDER', 'Monte a expressão usando as palavras disponíveis.', 'Monte “Meu nome é Minji.”', '[]'::jsonb, '["민지예요.","이름은","제"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '["제 이름은 민지예요."]'::jsonb, '{"accepted":["제 이름은 민지예요."]}'::jsonb, 'Use a expressão como um bloco completo, sem precisar analisar cada partícula.', '1', 'Equipe de conteúdo Tec Escola', 'STAGING', 'PEDAGOGICAL_REVIEW_PENDING', 'ko_v2b_u4_l4_word_order', '5', null, '[]'::jsonb);

do $$ begin
  if current_setting('transaction_read_only')::boolean then raise exception 'TEC_IDIOMAS_V4_READ_ONLY'; end if;
  if not exists (select 1 from information_schema.columns where table_schema='public' and table_name='tec_english_exercises' and column_name='skill_code') then raise exception 'TEC_IDIOMAS_V4_ADAPTIVE_SCHEMA_REQUIRED'; end if;
  if exists (select 1 from _v4_courses e join public.tec_english_courses a using (course_code) where row(a.content_version,a.title,a.description,a.author,a.publication_status,a.review_status,a.xp_per_lesson,a.is_test_fixture) is distinct from row(e.content_version,e.title,e.description,e.author,e.publication_status,e.review_status,e.xp_per_lesson,e.is_test_fixture)) then raise exception 'TEC_IDIOMAS_V4_COURSE_CONFLICT'; end if;
  if exists (select 1 from _v4_units e join public.tec_english_units a using (id) where row(a.course_code,a.position,a.title,a.description,a.content_version,a.author,a.publication_status,a.review_status) is distinct from row(e.course_code,e.position,e.title,e.description,e.content_version,e.author,e.publication_status,e.review_status)) then raise exception 'TEC_IDIOMAS_V4_UNIT_CONFLICT'; end if;
  if exists (select 1 from _v4_lessons e join public.tec_english_lessons a using (id) where row(a.unit_id,a.position,a.title,a.introduction,a.xp_reward,a.content_version,a.author,a.publication_status,a.review_status) is distinct from row(e.unit_id,e.position,e.title,e.introduction,e.xp_reward,e.content_version,e.author,e.publication_status,e.review_status)) then raise exception 'TEC_IDIOMAS_V4_LESSON_CONFLICT'; end if;
  if exists (select 1 from _v4_exercises e join public.tec_english_exercises a using (id) where row(a.lesson_id,a.position,a.exercise_type,a.instruction,a.prompt,a.options,a.word_bank,a.left_items,a.right_items,a.audio_text,a.accepted_answers,a.answer_key,a.explanation,a.content_version,a.author,a.publication_status,a.review_status,a.skill_code,a.difficulty_level,a.dialogue_speaker,a.dialogue_context) is distinct from row(e.lesson_id,e.position,e.exercise_type,e.instruction,e.prompt,e.options,e.word_bank,e.left_items,e.right_items,e.audio_text,e.accepted_answers,e.answer_key,e.explanation,e.content_version,e.author,e.publication_status,e.review_status,e.skill_code,e.difficulty_level,e.dialogue_speaker,e.dialogue_context)) then raise exception 'TEC_IDIOMAS_V4_EXERCISE_CONFLICT'; end if;
end $$;

insert into public.tec_english_courses(course_code,content_version,title,description,author,publication_status,review_status,xp_per_lesson,is_test_fixture) select course_code,content_version,title,description,author,publication_status,review_status,xp_per_lesson,is_test_fixture from _v4_courses on conflict (course_code) do nothing;
insert into public.tec_english_units(id,course_code,position,title,description,content_version,author,publication_status,review_status) select id,course_code,position,title,description,content_version,author,publication_status,review_status from _v4_units on conflict (id) do nothing;
insert into public.tec_english_lessons(id,unit_id,position,title,introduction,xp_reward,content_version,author,publication_status,review_status) select id,unit_id,position,title,introduction,xp_reward,content_version,author,publication_status,review_status from _v4_lessons on conflict (id) do nothing;
insert into public.tec_english_exercises(id,lesson_id,position,exercise_type,instruction,prompt,options,word_bank,left_items,right_items,audio_text,accepted_answers,answer_key,explanation,content_version,author,publication_status,review_status,skill_code,difficulty_level,dialogue_speaker,dialogue_context) select id,lesson_id,position,exercise_type,instruction,prompt,options,word_bank,left_items,right_items,audio_text,accepted_answers,answer_key,explanation,content_version,author,publication_status,review_status,skill_code,difficulty_level,dialogue_speaker,dialogue_context from _v4_exercises on conflict (id) do nothing;

do $$ begin
  if (select count(*) from public.tec_english_units where course_code='TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER') <> 4 or (select count(*) from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id=lesson.unit_id where unit.course_code='TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER') <> 16 or (select count(*) from public.tec_english_exercises exercise join public.tec_english_lessons lesson on lesson.id=exercise.lesson_id join public.tec_english_units unit on unit.id=lesson.unit_id where unit.course_code='TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER') <> 76 then raise exception 'TEC_IDIOMAS_V4_CONTENT_COUNT_MISMATCH'; end if;
  if (select count(*) from public.tec_english_units where course_code='TEC_SPANISH_FOUNDATIONS_V2_BEGINNER') <> 4 or (select count(*) from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id=lesson.unit_id where unit.course_code='TEC_SPANISH_FOUNDATIONS_V2_BEGINNER') <> 16 or (select count(*) from public.tec_english_exercises exercise join public.tec_english_lessons lesson on lesson.id=exercise.lesson_id join public.tec_english_units unit on unit.id=lesson.unit_id where unit.course_code='TEC_SPANISH_FOUNDATIONS_V2_BEGINNER') <> 76 then raise exception 'TEC_IDIOMAS_V4_CONTENT_COUNT_MISMATCH'; end if;
  if (select count(*) from public.tec_english_units where course_code='TEC_KOREAN_FOUNDATIONS_V2_BEGINNER') <> 4 or (select count(*) from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id=lesson.unit_id where unit.course_code='TEC_KOREAN_FOUNDATIONS_V2_BEGINNER') <> 16 or (select count(*) from public.tec_english_exercises exercise join public.tec_english_lessons lesson on lesson.id=exercise.lesson_id join public.tec_english_units unit on unit.id=lesson.unit_id where unit.course_code='TEC_KOREAN_FOUNDATIONS_V2_BEGINNER') <> 72 then raise exception 'TEC_IDIOMAS_V4_CONTENT_COUNT_MISMATCH'; end if;
  if exists (select 1 from public.tec_english_courses where course_code in ('TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER', 'TEC_SPANISH_FOUNDATIONS_V2_BEGINNER', 'TEC_KOREAN_FOUNDATIONS_V2_BEGINNER') and (publication_status <> 'STAGING' or review_status <> 'PEDAGOGICAL_REVIEW_PENDING' or is_test_fixture)) then raise exception 'TEC_IDIOMAS_V4_REVIEW_STATE_CONFLICT'; end if;
end $$;

create or replace function private.tec_idiomas_v3_course_allowed(p_course_code text)
returns boolean language sql immutable security definer set search_path = '' as $$
  select p_course_code in (
    'TEC_ENGLISH_FOUNDATIONS_V2_EXPANSION',
    'TEC_SPANISH_FOUNDATIONS_V1',
    'TEC_KOREAN_FOUNDATIONS_V1',
    'TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER',
    'TEC_SPANISH_FOUNDATIONS_V2_BEGINNER',
    'TEC_KOREAN_FOUNDATIONS_V2_BEGINNER'
  );
$$;
revoke all on function private.tec_idiomas_v3_course_allowed(text) from public, anon, authenticated;

create or replace function private.tec_idiomas_v3_course_version_allowed(p_course_code text, p_content_version integer)
returns boolean language sql immutable security definer set search_path = '' as $$
  select (p_course_code, p_content_version) in (
    ('TEC_ENGLISH_FOUNDATIONS_V2_EXPANSION', 1),
    ('TEC_SPANISH_FOUNDATIONS_V1', 1),
    ('TEC_KOREAN_FOUNDATIONS_V1', 1),
    ('TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER', 1),
    ('TEC_SPANISH_FOUNDATIONS_V2_BEGINNER', 1),
    ('TEC_KOREAN_FOUNDATIONS_V2_BEGINNER', 1)
  );
$$;
revoke all on function private.tec_idiomas_v3_course_version_allowed(text, integer) from public, anon, authenticated;

create or replace function private.tec_idiomas_v4_manifest_matches(p_course_code text, p_content_version integer)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from private.tec_idiomas_v4_content_manifest manifest
    where manifest.course_code = p_course_code and manifest.content_version = p_content_version
      and manifest.content_fingerprint = private.tec_english_course_fingerprint(p_course_code, p_content_version));
$$;
revoke all on function private.tec_idiomas_v4_manifest_matches(text, integer) from public, anon, authenticated;

create or replace function private.tec_idiomas_v3_course_content_eligible(p_course_code text, p_content_version integer)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.tec_english_courses course
    where course.course_code = p_course_code and course.content_version = p_content_version
      and private.tec_idiomas_v3_course_version_allowed(course.course_code, course.content_version)
      and not course.is_test_fixture and course.publication_status in ('STAGING', 'PUBLISHED')
      and case course.course_code
         when 'TEC_ENGLISH_FOUNDATIONS_V2_EXPANSION' then (select count(*) = 4 from public.tec_english_units unit where unit.course_code = course.course_code) and (select count(*) = 16 from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code) and (select count(*) = 112 from public.tec_english_exercises exercise join public.tec_english_lessons lesson on lesson.id = exercise.lesson_id join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code)
         when 'TEC_SPANISH_FOUNDATIONS_V1' then (select count(*) = 2 from public.tec_english_units unit where unit.course_code = course.course_code) and (select count(*) = 8 from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code) and (select count(*) = 56 from public.tec_english_exercises exercise join public.tec_english_lessons lesson on lesson.id = exercise.lesson_id join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code)
         when 'TEC_KOREAN_FOUNDATIONS_V1' then (select count(*) = 2 from public.tec_english_units unit where unit.course_code = course.course_code) and (select count(*) = 8 from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code) and (select count(*) = 56 from public.tec_english_exercises exercise join public.tec_english_lessons lesson on lesson.id = exercise.lesson_id join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code)
         when 'TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER' then (select count(*) = 4 from public.tec_english_units unit where unit.course_code = course.course_code) and (select count(*) = 16 from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code) and (select count(*) = 76 from public.tec_english_exercises exercise join public.tec_english_lessons lesson on lesson.id = exercise.lesson_id join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code) and private.tec_idiomas_v4_manifest_matches(course.course_code, course.content_version)
         when 'TEC_SPANISH_FOUNDATIONS_V2_BEGINNER' then (select count(*) = 4 from public.tec_english_units unit where unit.course_code = course.course_code) and (select count(*) = 16 from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code) and (select count(*) = 76 from public.tec_english_exercises exercise join public.tec_english_lessons lesson on lesson.id = exercise.lesson_id join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code) and private.tec_idiomas_v4_manifest_matches(course.course_code, course.content_version)
         when 'TEC_KOREAN_FOUNDATIONS_V2_BEGINNER' then (select count(*) = 4 from public.tec_english_units unit where unit.course_code = course.course_code) and (select count(*) = 16 from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code) and (select count(*) = 72 from public.tec_english_exercises exercise join public.tec_english_lessons lesson on lesson.id = exercise.lesson_id join public.tec_english_units unit on unit.id = lesson.unit_id where unit.course_code = course.course_code) and private.tec_idiomas_v4_manifest_matches(course.course_code, course.content_version)
         else false
      end
      and not exists (select 1 from public.tec_english_units unit where unit.course_code = course.course_code
        and (unit.content_version <> course.content_version or unit.publication_status not in ('STAGING', 'PUBLISHED')))
      and not exists (select 1 from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id = lesson.unit_id
        where unit.course_code = course.course_code and (lesson.content_version <> course.content_version or lesson.publication_status not in ('STAGING', 'PUBLISHED')))
      and not exists (select 1 from public.tec_english_exercises exercise join public.tec_english_lessons lesson on lesson.id = exercise.lesson_id join public.tec_english_units unit on unit.id = lesson.unit_id
        where unit.course_code = course.course_code and (exercise.content_version <> course.content_version or exercise.publication_status not in ('STAGING', 'PUBLISHED')
          or exercise.skill_code is null or exercise.difficulty_level not between 1 and 5))
      and not exists (select 1 from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id = lesson.unit_id left join public.tec_english_exercises exercise on exercise.lesson_id = lesson.id
        where unit.course_code = course.course_code group by lesson.id having
          case when course.course_code in ('TEC_ENGLISH_FOUNDATIONS_V2_EXPANSION','TEC_SPANISH_FOUNDATIONS_V1','TEC_KOREAN_FOUNDATIONS_V1') then count(exercise.id) <> 7
               else count(exercise.id) not between 4 and 5 end));
$$;
revoke all on function private.tec_idiomas_v3_course_content_eligible(text, integer) from public, anon, authenticated;

create or replace function private.tec_english_course_available(
  p_institution_id uuid,
  p_course_code text,
  p_test_mode boolean
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.tec_english_courses course
     where course.course_code = p_course_code
       and (
         (p_test_mode and course.is_test_fixture)
         or (
           not p_test_mode and not course.is_test_fixture
           and (
             (
               private.tec_idiomas_v3_course_version_allowed(course.course_code, course.content_version)
               and private.tec_idiomas_v3_course_content_eligible(course.course_code, course.content_version)
               and exists (
                 select 1 from public.institutions institution
                  where institution.id = p_institution_id and institution.active
               )
             )
             or (
               not private.tec_idiomas_v3_course_allowed(course.course_code)
               and course.publication_status = 'PUBLISHED'
               and course.review_status = 'PEDAGOGICAL_REVIEWED'
               and exists (
                 select 1 from public.tec_english_pedagogical_reviews review
                  where review.course_code = course.course_code
                    and review.content_version = course.content_version
                    and review.decision = 'APPROVED'
                    and review.snapshot_fingerprint = private.tec_english_course_fingerprint(course.course_code, course.content_version)
               )
               and exists (
                 select 1 from public.tec_english_course_releases release
                 join public.institutions institution on institution.id = release.institution_id
                  where release.course_code = course.course_code
                    and release.content_version = course.content_version
                    and release.institution_id = p_institution_id
                    and release.enabled and institution.active
               )
             )
           )
         )
       )
  );
$$;
revoke all on function private.tec_english_course_available(uuid, text, boolean) from public, anon, authenticated;

create or replace function private.tec_english_course_snapshot(p_course_code text, p_content_version integer)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'course', pg_catalog.jsonb_build_object(
      'course_code', course.course_code, 'content_version', course.content_version,
      'title', course.title, 'description', course.description,
      'author', course.author, 'xp_per_lesson', course.xp_per_lesson
    ),
    'units', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'id', unit.id, 'position', unit.position, 'title', unit.title,
        'description', unit.description, 'content_version', unit.content_version,
        'author', unit.author, 'lessons', coalesce((
          select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'id', lesson.id, 'position', lesson.position, 'title', lesson.title,
            'introduction', lesson.introduction, 'xp_reward', lesson.xp_reward,
            'content_version', lesson.content_version, 'author', lesson.author,
            'exercises', coalesce((
              select pg_catalog.jsonb_agg((pg_catalog.jsonb_build_object(
                'id', exercise.id, 'position', exercise.position,
                'type', exercise.exercise_type, 'instruction', exercise.instruction,
                'prompt', exercise.prompt, 'options', exercise.options,
                'word_bank', exercise.word_bank, 'left_items', exercise.left_items,
                'right_items', exercise.right_items, 'audio_text', exercise.audio_text,
                'accepted_answers', exercise.accepted_answers, 'answer_key', exercise.answer_key,
                'explanation', exercise.explanation,
                'content_version', exercise.content_version, 'author', exercise.author
              ) || case when p_course_code in (
                   'TEC_ENGLISH_FOUNDATIONS_V2',
                   'TEC_ENGLISH_FOUNDATIONS_V2_EXPANSION',
                   'TEC_SPANISH_FOUNDATIONS_V1',
                   'TEC_KOREAN_FOUNDATIONS_V1',
                   'TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER',
                   'TEC_SPANISH_FOUNDATIONS_V2_BEGINNER',
                   'TEC_KOREAN_FOUNDATIONS_V2_BEGINNER'
                 ) or p_course_code like 'TEC_ENGLISH_FOUNDATIONS_V2_TEST%'
                   then pg_catalog.jsonb_build_object('skill_code', exercise.skill_code,
                     'difficulty_level', exercise.difficulty_level, 'dialogue_speaker', exercise.dialogue_speaker,
                     'dialogue_context', exercise.dialogue_context)
                   else '{}'::jsonb end) order by exercise.position)
                from public.tec_english_exercises exercise where exercise.lesson_id = lesson.id
            ), '[]'::jsonb)
          ) order by lesson.position)
            from public.tec_english_lessons lesson where lesson.unit_id = unit.id
        ), '[]'::jsonb)
      ) order by unit.position)
        from public.tec_english_units unit where unit.course_code = course.course_code
    ), '[]'::jsonb)
  )
    from public.tec_english_courses course
   where course.course_code = p_course_code and course.content_version = p_content_version;
$$;
revoke all on function private.tec_english_course_snapshot(text, integer) from public, anon, authenticated;

create or replace function private.tec_english_public_exercise(p_exercise_id text)
returns jsonb
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select jsonb_build_object(
    'id', exercise.id, 'position', exercise.position, 'type', exercise.exercise_type,
    'instruction', exercise.instruction, 'prompt', exercise.prompt,
    'options', exercise.options, 'word_bank', exercise.word_bank,
    'left_items', exercise.left_items, 'right_items', exercise.right_items,
    'audio_text', exercise.audio_text
  )
  || case when unit.course_code in (
       'TEC_ENGLISH_FOUNDATIONS_V2',
                   'TEC_ENGLISH_FOUNDATIONS_V2_EXPANSION',
                   'TEC_SPANISH_FOUNDATIONS_V1',
                   'TEC_KOREAN_FOUNDATIONS_V1',
                   'TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER',
                   'TEC_SPANISH_FOUNDATIONS_V2_BEGINNER',
                   'TEC_KOREAN_FOUNDATIONS_V2_BEGINNER'
     ) or unit.course_code like 'TEC_ENGLISH_FOUNDATIONS_V2_TEST%'
       then jsonb_build_object('skill_code', exercise.skill_code,
         'difficulty_level', exercise.difficulty_level, 'dialogue_speaker', exercise.dialogue_speaker,
         'dialogue_context', exercise.dialogue_context)
       else '{}'::jsonb end
    from public.tec_english_exercises exercise
    join public.tec_english_lessons lesson on lesson.id = exercise.lesson_id
    join public.tec_english_units unit on unit.id = lesson.unit_id
   where exercise.id = p_exercise_id;
$$;
revoke all on function private.tec_english_public_exercise(text) from public, anon, authenticated;

insert into private.tec_idiomas_v4_content_manifest(course_code, content_version, content_fingerprint)
select course.course_code, course.content_version, private.tec_english_course_fingerprint(course.course_code, course.content_version)
  from public.tec_english_courses course where course.course_code in ('TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER', 'TEC_SPANISH_FOUNDATIONS_V2_BEGINNER', 'TEC_KOREAN_FOUNDATIONS_V2_BEGINNER')
on conflict (course_code) do nothing;

create or replace function private.tec_idiomas_v4_legacy_access_allowed(p_institution_id uuid, p_student_id uuid, p_course_code text)
returns boolean language plpgsql stable security definer set search_path = '' as $$
declare
  v_beginner_code text := case p_course_code
    when 'TEC_ENGLISH_FOUNDATIONS_V2_EXPANSION' then 'TEC_ENGLISH_FOUNDATIONS_V4_BEGINNER'
    when 'TEC_SPANISH_FOUNDATIONS_V1' then 'TEC_SPANISH_FOUNDATIONS_V2_BEGINNER'
    when 'TEC_KOREAN_FOUNDATIONS_V1' then 'TEC_KOREAN_FOUNDATIONS_V2_BEGINNER'
    else null end;
  v_legacy_activity boolean;
  v_completed_intro integer;
begin
  if v_beginner_code is null then return true; end if;
  select exists (select 1 from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id = lesson.unit_id
    where unit.course_code = p_course_code and (
      exists (select 1 from public.tec_english_lesson_progress progress where progress.lesson_id = lesson.id and progress.institution_id = p_institution_id and progress.student_id = p_student_id)
      or exists (select 1 from public.tec_english_lesson_sessions session where session.lesson_id = lesson.id and session.institution_id = p_institution_id and session.student_id = p_student_id)
    )) into v_legacy_activity;
  if v_legacy_activity then return true; end if;
  select count(*)::integer into v_completed_intro from public.tec_english_lessons lesson join public.tec_english_units unit on unit.id = lesson.unit_id
   where unit.course_code = v_beginner_code and exists (select 1 from public.tec_english_lesson_progress progress
     where progress.lesson_id = lesson.id and progress.institution_id = p_institution_id and progress.student_id = p_student_id);
  return v_completed_intro = 16;
end;
$$;
revoke all on function private.tec_idiomas_v4_legacy_access_allowed(uuid, uuid, text) from public, anon, authenticated;

create or replace function public.start_tec_language_lesson_v1(p_institution_id uuid, p_course_code text, p_lesson_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_student_id uuid := private.tec_english_current_student_id(p_institution_id);
  v_session_id uuid;
begin
  if not private.tec_idiomas_v3_course_allowed(p_course_code)
     or private.tec_english_test_mode()
     or not private.tec_english_course_available(p_institution_id, p_course_code, false)
     or not private.tec_english_lesson_ready(p_lesson_id, false)
     or not exists (select 1 from public.tec_english_lessons lesson
       join public.tec_english_units unit on unit.id = lesson.unit_id
       where lesson.id = p_lesson_id and unit.course_code = p_course_code) then
    raise exception 'TEC_ENGLISH_CONTENT_NOT_APPROVED' using errcode = '42501';
  end if;
  if not private.tec_idiomas_v4_legacy_access_allowed(p_institution_id, v_student_id, p_course_code) then
    raise exception 'TEC_ENGLISH_BEGINNER_PATH_REQUIRED' using errcode = '42501';
  end if;

  if exists (
    select 1 from public.tec_english_lessons target
    join public.tec_english_units target_unit on target_unit.id = target.unit_id
    join public.tec_english_lessons previous on true
    join public.tec_english_units previous_unit on previous_unit.id = previous.unit_id
    where target.id = p_lesson_id and target_unit.course_code = p_course_code
      and previous_unit.course_code = p_course_code
      and (previous_unit.position, previous.position) < (target_unit.position, target.position)
      and not exists (select 1 from public.tec_english_lesson_progress progress
        where progress.institution_id = p_institution_id and progress.student_id = v_student_id and progress.lesson_id = previous.id)
  ) then raise exception 'TEC_ENGLISH_LESSON_LOCKED' using errcode = '42501'; end if;

  select session.id into v_session_id from public.tec_english_lesson_sessions session
   where session.institution_id = p_institution_id and session.student_id = v_student_id
     and session.lesson_id = p_lesson_id and session.status = 'IN_PROGRESS'
   order by session.updated_at desc limit 1 for update;
  if v_session_id is null then
    insert into public.tec_english_lesson_sessions(institution_id, student_id, lesson_id)
    values (p_institution_id, v_student_id, p_lesson_id)
    on conflict (institution_id, student_id, lesson_id) where status = 'IN_PROGRESS' do nothing
    returning id into v_session_id;
    if v_session_id is null then
      select session.id into v_session_id from public.tec_english_lesson_sessions session
       where session.institution_id = p_institution_id and session.student_id = v_student_id
         and session.lesson_id = p_lesson_id and session.status = 'IN_PROGRESS' for update;
    end if;
  end if;
  return private.tec_english_session_payload(v_session_id, v_student_id, p_institution_id);
end;
$$;

create or replace function public.get_tec_language_session_v1(p_institution_id uuid, p_course_code text, p_session_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_student_id uuid := private.tec_english_current_student_id(p_institution_id);
  v_lesson_id text;
  v_course_code text;
  v_result jsonb;
begin
  select session.lesson_id, unit.course_code into v_lesson_id, v_course_code
    from public.tec_english_lesson_sessions session
    join public.tec_english_lessons lesson on lesson.id = session.lesson_id
    join public.tec_english_units unit on unit.id = lesson.unit_id
   where session.id = p_session_id and session.student_id = v_student_id and session.institution_id = p_institution_id;
  if not found or v_course_code is distinct from p_course_code
     or not private.tec_idiomas_v3_course_allowed(p_course_code)
     or private.tec_english_test_mode()
     or not private.tec_english_course_available(p_institution_id, p_course_code, false)
     or not private.tec_english_lesson_ready(v_lesson_id, false) then
    raise exception 'TEC_ENGLISH_SESSION_NOT_FOUND' using errcode = '42501';
  end if;
  select private.tec_english_session_payload(p_session_id, v_student_id, p_institution_id) into v_result;
  return v_result;
end;
$$;

create or replace function public.submit_tec_language_answer_v1(
  p_institution_id uuid, p_course_code text, p_session_id uuid,
  p_exercise_id text, p_response jsonb, p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_student_id uuid := private.tec_english_current_student_id(p_institution_id);
  v_course_code text;
  v_lesson_id text;
  v_created_stats_row boolean := false;
  v_was_replay boolean := false;
  v_had_xp_event boolean := false;
  v_old_stats public.tec_english_student_stats%rowtype;
  v_result jsonb;
  v_awarded_xp integer := 0;
  v_today date := (now() at time zone 'America/Sao_Paulo')::date;
  v_language_stats public.tec_language_course_stats_v1%rowtype;
begin
  select lesson.id, unit.course_code into v_lesson_id, v_course_code
    from public.tec_english_lesson_sessions session
    join public.tec_english_lessons lesson on lesson.id = session.lesson_id
    join public.tec_english_units unit on unit.id = lesson.unit_id
   where session.id = p_session_id and session.student_id = v_student_id and session.institution_id = p_institution_id;
  if not found or v_course_code is distinct from p_course_code
     or not private.tec_idiomas_v3_course_allowed(p_course_code)
     or private.tec_english_test_mode()
     or not private.tec_english_course_available(p_institution_id, p_course_code, false)
     or not private.tec_english_lesson_ready(v_lesson_id, false) then
    raise exception 'TEC_ENGLISH_SESSION_NOT_FOUND' using errcode = '42501';
  end if;

  select exists (select 1 from public.tec_english_answer_attempts attempt
    where attempt.student_id = v_student_id and attempt.idempotency_key = p_idempotency_key) into v_was_replay;
  select exists (select 1 from public.tec_english_xp_events event
    where event.institution_id = p_institution_id and event.student_id = v_student_id
      and event.event_key = 'lesson:' || v_lesson_id) into v_had_xp_event;

  -- The legacy scorer still maintains global English totals. Lock and restore
  -- that row around the shared grading/progress transaction so the new course
  -- writes its visible XP and streak only into its own course-scoped row.
  insert into public.tec_english_student_stats(institution_id, student_id)
    values (p_institution_id, v_student_id)
    on conflict (institution_id, student_id) do nothing
    returning true into v_created_stats_row;
  v_created_stats_row := coalesce(v_created_stats_row, false);
  select * into v_old_stats from public.tec_english_student_stats stats
   where stats.institution_id = p_institution_id and stats.student_id = v_student_id for update;

  v_result := private.tec_english_submit_answer_unchecked_v1(
    p_institution_id, p_session_id, p_exercise_id, p_response, p_idempotency_key
  );
  v_awarded_xp := coalesce((v_result ->> 'xp_awarded')::integer, 0);

  -- The shared scorer creates a global English XP event. Keep Spanish and
  -- Korean XP isolated in tec_language_course_stats_v1 by removing only the
  -- event newly created by this transaction; pre-existing events are retained.
  if not v_had_xp_event and v_awarded_xp > 0 then
    delete from public.tec_english_xp_events event
     where event.institution_id = p_institution_id and event.student_id = v_student_id
       and event.event_key = 'lesson:' || v_lesson_id;
  end if;

  if v_created_stats_row then
    delete from public.tec_english_student_stats stats
     where stats.institution_id = p_institution_id and stats.student_id = v_student_id;
  else
    update public.tec_english_student_stats stats set
      xp = v_old_stats.xp, current_streak = v_old_stats.current_streak,
      longest_streak = v_old_stats.longest_streak, last_study_date = v_old_stats.last_study_date,
      updated_at = v_old_stats.updated_at
     where stats.institution_id = p_institution_id and stats.student_id = v_student_id;
  end if;

  if not v_was_replay and v_awarded_xp > 0 then
    insert into public.tec_language_course_stats_v1(institution_id, student_id, course_code, xp, current_streak, longest_streak, last_study_date)
    values (p_institution_id, v_student_id, p_course_code, v_awarded_xp, 1, 1, v_today)
    on conflict (institution_id, student_id, course_code) do update set
      xp = public.tec_language_course_stats_v1.xp + excluded.xp,
      current_streak = case
        when public.tec_language_course_stats_v1.last_study_date = v_today then public.tec_language_course_stats_v1.current_streak
        when public.tec_language_course_stats_v1.last_study_date = v_today - 1 then public.tec_language_course_stats_v1.current_streak + 1
        else 1 end,
      longest_streak = greatest(public.tec_language_course_stats_v1.longest_streak,
        case when public.tec_language_course_stats_v1.last_study_date = v_today then public.tec_language_course_stats_v1.current_streak
             when public.tec_language_course_stats_v1.last_study_date = v_today - 1 then public.tec_language_course_stats_v1.current_streak + 1
             else 1 end),
      last_study_date = v_today, updated_at = now();
  end if;

  select * into v_language_stats from public.tec_language_course_stats_v1 stats
   where stats.institution_id = p_institution_id and stats.student_id = v_student_id and stats.course_code = p_course_code;
  v_result := jsonb_set(v_result, '{total_xp}', to_jsonb(coalesce(v_language_stats.xp, 0)), true);
  v_result := jsonb_set(v_result, '{current_streak}', to_jsonb(coalesce(v_language_stats.current_streak, 0)), true);
  return v_result;
end;
$$;

-- Keep V3 sessions and XP inside the course-scoped runtime. The legacy V1
-- wrappers must never start, resume, or grade a V3 lesson through old totals.
create or replace function public.start_tec_english_lesson_v1(p_institution_id uuid, p_lesson_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_test_mode boolean := private.tec_english_test_mode();
  v_course_code text := case when private.tec_english_test_mode() then 'TEC_ENGLISH_FOUNDATIONS_TEST' else 'TEC_ENGLISH_FOUNDATIONS' end;
begin
  perform private.tec_english_current_student_id(p_institution_id);
  if not private.tec_english_course_available(p_institution_id, v_course_code, v_test_mode) then
    raise exception 'TEC_ENGLISH_COURSE_NOT_AVAILABLE' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.tec_english_lessons lesson
    join public.tec_english_units unit on unit.id = lesson.unit_id
    where lesson.id = p_lesson_id and unit.course_code = v_course_code
  ) or not private.tec_english_lesson_ready(p_lesson_id, v_test_mode) then
    raise exception 'TEC_ENGLISH_CONTENT_NOT_APPROVED' using errcode = '42501';
  end if;
  return private.tec_english_start_lesson_unchecked_v1(p_institution_id, p_lesson_id);
end;
$$;

create or replace function public.get_tec_english_session_v1(p_institution_id uuid, p_session_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_student_id uuid := private.tec_english_current_student_id(p_institution_id);
  v_test_mode boolean := private.tec_english_test_mode();
  v_expected_course text := case when private.tec_english_test_mode() then 'TEC_ENGLISH_FOUNDATIONS_TEST' else 'TEC_ENGLISH_FOUNDATIONS' end;
  v_lesson_id text;
  v_course_code text;
begin
  select session.lesson_id, unit.course_code into v_lesson_id, v_course_code
    from public.tec_english_lesson_sessions session
    join public.tec_english_lessons lesson on lesson.id = session.lesson_id
    join public.tec_english_units unit on unit.id = lesson.unit_id
   where session.id = p_session_id and session.institution_id = p_institution_id
     and session.student_id = v_student_id;
  if not found or v_course_code <> v_expected_course
     or not private.tec_english_course_available(p_institution_id, v_expected_course, v_test_mode)
     or not private.tec_english_lesson_ready(v_lesson_id, v_test_mode) then
    raise exception 'TEC_ENGLISH_SESSION_NOT_FOUND' using errcode = '42501';
  end if;
  return private.tec_english_get_session_unchecked_v1(p_institution_id, p_session_id);
end;
$$;

create or replace function public.submit_tec_english_answer_v1(
  p_institution_id uuid,
  p_session_id uuid,
  p_exercise_id text,
  p_response jsonb,
  p_idempotency_key uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_student_id uuid := private.tec_english_current_student_id(p_institution_id);
  v_test_mode boolean := private.tec_english_test_mode();
  v_expected_course text := case when private.tec_english_test_mode() then 'TEC_ENGLISH_FOUNDATIONS_TEST' else 'TEC_ENGLISH_FOUNDATIONS' end;
  v_lesson_id text;
  v_course_code text;
begin
  select session.lesson_id, unit.course_code into v_lesson_id, v_course_code
    from public.tec_english_lesson_sessions session
    join public.tec_english_lessons lesson on lesson.id = session.lesson_id
    join public.tec_english_units unit on unit.id = lesson.unit_id
   where session.id = p_session_id and session.institution_id = p_institution_id
     and session.student_id = v_student_id;
  if not found or v_course_code <> v_expected_course
     or not private.tec_english_course_available(p_institution_id, v_expected_course, v_test_mode)
     or not private.tec_english_lesson_ready(v_lesson_id, v_test_mode) then
    raise exception 'TEC_ENGLISH_SESSION_NOT_FOUND' using errcode = '42501';
  end if;
  return private.tec_english_submit_answer_unchecked_v1(
    p_institution_id, p_session_id, p_exercise_id, p_response, p_idempotency_key
  );
end;
$$;

revoke all on function public.get_tec_language_course_map_v1(uuid, text) from public, anon;
revoke all on function public.start_tec_language_lesson_v1(uuid, text, text) from public, anon;


commit;
